import numpy as np
def conv2d(x, k, b, stride=1, padding=0):
    # x:(N,Cin,H,W) k:(Cout,Cin,kh,kw)
    if padding:
        x = np.pad(x, ((0,0),(0,0),(padding,padding),(padding,padding)))
    N,_,H,W = x.shape
    Cout,_,kh,kw = k.shape
    oh = (H-kh)//stride+1; ow = (W-kw)//stride+1
    out = np.zeros((N,Cout,oh,ow))
    for n in range(N):
        for c in range(Cout):
            for i in range(oh):
                for j in range(ow):
                    patch = x[n,:, i*stride:i*stride+kh, j*stride:j*stride+kw]
                    out[n,c,i,j] = np.sum(patch*k[c]) + b[c]
    return out
